import{_ as e,c as a,o as r,a4 as t}from"./chunks/framework.4aTu-Nia.js";const m=JSON.parse('{"title":"微前端","description":"","frontmatter":{},"headers":[],"relativePath":"project/micro-frontend.md","filePath":"project/micro-frontend.md"}'),o={name:"project/micro-frontend.md"},n=t('<h1 id="微前端" tabindex="-1">微前端 <a class="header-anchor" href="#微前端" aria-label="Permalink to &quot;微前端&quot;">​</a></h1><p>微服务（后端）延伸</p><p>与传统前端架构相比，微前端具有以下区别：</p><ul><li>技术栈无关</li><li>独立部署：开发、发布及部署独立</li><li>模块化：可维护性、可扩展性，应用隔离</li><li>用户体验：小部件都可以独立加载和更新</li></ul><p><a href="https://cloud.tencent.com/developer/article/1967842" target="_blank" rel="noreferrer">初探 MicroApp，一个极致简洁的微前端框架 - 腾讯云开发者社区-腾讯云</a></p><p><a href="https://developer.aliyun.com/article/742576" target="_blank" rel="noreferrer">标准微前端架构在蚂蚁的落地实践-阿里云开发者社区</a> ^ab8b38</p><p>qiankun 侵入性强，沙箱坑较多</p><h2 id="自定义元素" tabindex="-1">自定义元素 <a class="header-anchor" href="#自定义元素" aria-label="Permalink to &quot;自定义元素&quot;">​</a></h2><p><a href="https://javascript.info/custom-elements" target="_blank" rel="noreferrer">Custom elements</a></p><p>浏览器原生支持的组件</p><p>connectedCallback 挂载</p><p>attributeChangedCallback &amp; attributeChangedCallback 观察属性变化，回调，数据驱动调用</p><p>用 polyfill 可支持所有浏览器</p><p>通信：CustomEvent ^719480</p><p>SSI 服务端渲染包含，比较老的技术 缺点：最慢的片段决定了整个页面的响应时间</p><p><a href="https://micro-frontends.org/" target="_blank" rel="noreferrer">微前端——将微服务理念扩展到前端开发</a></p><p><a href="https://zhuanlan.zhihu.com/p/571794756" target="_blank" rel="noreferrer">微前端方案 qiankun 只是更完善的 single-spa - 知乎</a></p><h2 id="跨域共享数据-替代cookie" tabindex="-1">跨域共享数据（替代cookie） <a class="header-anchor" href="#跨域共享数据-替代cookie" aria-label="Permalink to &quot;跨域共享数据（替代cookie）&quot;">​</a></h2><p>cookie 不支持跨域 postmessage + localstorage</p><p>安全生，被 JS 读取，比如第三方广告、统计</p>',20),l=[n];function p(i,c,s,h,d,_){return r(),a("div",null,l)}const u=e(o,[["render",p]]);export{m as __pageData,u as default};
